INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT147-S4-Q17$batch10$, 147, 4, 17, $batch10$Main Conclusion$batch10$, $batch10$It is pointless to debate the truth of the law of noncontradiction, a fundamental logical principle according to which two statements that contradict each other cannot both be true. For a debate to be productive, participants must hold some basic principles in common. But the principles held in common in a debate over the law of noncontradiction would be much less certain than that law, so it matters little whether the law of noncontradiction can be defended on the basis of those principles.$batch10$, $batch10$Which one of the following most accurately expresses the overall conclusion drawn in the argument?$batch10$, $batch10$A$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=147 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q17$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$It is pointless to debate the truth of the law of noncontradiction.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q17$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$Statements that contradict each other cannot both be true.$batch10$, $batch10$Definition$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q17$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$The participants in a productive debate must hold at least some basic principles in common.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q17$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$The law of noncontradiction is a principle that the participants in a productive debate must hold in common.$batch10$, $batch10$Not Stated$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q17$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$Any principles that could be used to defend the law of noncontradiction are less certain than it is.$batch10$, $batch10$Premise$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q17$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT147-S4-Q17$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$It is pointless to debate the truth of the law of noncontradiction.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$A productive debate requires participants to share some basic principles. In this debate, those shared principles would be less certain than the law itself, so it matters little whether the law can be defended from them.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The first sentence makes the claim, and the rest explains why. The "so" in the last sentence introduces an intermediate step, which in turn supports the first sentence.$batch10$), (3, $batch10$Goal$batch10$, $batch10$Debating the law of noncontradiction is pointless.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT147-S4-Q17$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is the first sentence, which everything else supports.$batch10$), ($batch10$B$batch10$, $batch10$This is the content of the law, given as background.$batch10$), ($batch10$C$batch10$, $batch10$This is the first piece of support.$batch10$), ($batch10$D$batch10$, $batch10$The argument never says the law itself must be a shared principle.$batch10$), ($batch10$E$batch10$, $batch10$This is part of the support for why debating the law is pointless.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT147-S4-Q17$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
